def html(title, sections, other_title, other_href):
    body = "".join("<h2>%s</h2><p>%s</p>" % (h, p) for h, p in sections)
    return """<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>%(title)s — سامانهٔ آزمون آنلاین</title>
<meta name="description" content="%(title)s سامانهٔ آزمون آنلاین onlineexam.ir">
<style>
@font-face{font-family:'Vazirmatn';font-style:normal;font-weight:400;font-display:swap;src:url(/fonts/Vazirmatn-400.woff2) format('woff2')}
@font-face{font-family:'Vazirmatn';font-style:normal;font-weight:700;font-display:swap;src:url(/fonts/Vazirmatn-700.woff2) format('woff2')}
@font-face{font-family:'Vazirmatn';font-style:normal;font-weight:800 900;font-display:swap;src:url(/fonts/Vazirmatn-800.woff2) format('woff2')}
/* V291 — فونت وزیرمتن (قبلاً فقط نام فونت بود و در دسکتاپ Tahoma نمایش داده می‌شد) */
body{margin:0;font-family:'Vazirmatn',Tahoma,'Segoe UI',sans-serif;background:#eef3f8;color:#1F2530;padding:16px}
.card{background:#fff;border-radius:22px;box-shadow:0 14px 40px rgba(31,59,87,.12);padding:28px 24px;max-width:760px;margin:0 auto}
h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:22px 0 6px;color:#1f3b57}p{margin:0;color:#3d4756;font-size:14.5px;line-height:2}
.meta{color:#6b7684;font-size:13px}.nav{margin-top:26px;font-size:14px}.nav a{color:#1877d2;text-decoration:none;margin-left:14px}
@media (prefers-color-scheme:dark){body{background:#0f1620;color:#e6edf5}.card{background:#172230;box-shadow:none}h2{color:#9fc4ea}p{color:#cfd8e3}.meta{color:#8b97a6}}
</style>
</head>
<body><div class="card">
<h1>%(title)s</h1>
<div class="meta">سامانهٔ آزمون آنلاین · آخرین به‌روزرسانی: %(updated)s</div>
%(body)s
<div class="nav"><a href="%(other_href)s">%(other_title)s</a><a href="/">بازگشت به سامانه</a></div>
</div></body></html>
""" % dict(title=title, updated=UPDATED, body=body, other_title=other_title, other_href=other_href)

def write_pages(site_dir):
    import os
    open(os.path.join(site_dir, "terms.html"), "w", encoding="utf-8").write(html("شرایط استفاده", TERMS, "حریم خصوصی", "/privacy.html"))
    open(os.path.join(site_dir, "privacy.html"), "w", encoding="utf-8").write(html("حریم خصوصی", PRIVACY, "شرایط استفاده", "/terms.html"))

if __name__ == "__main__":
    import os, sys
    write_pages(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
    print("terms.html / privacy.html نوشته شد")
